//! Pins the result types that `x86_builtin_types::result_type` assigns to the
//! lane-128 and wide-vector builtins.
//!
//! `x86_builtin_types.rs` is generated by `scripts/gen_x86_builtin_types.py`
//! and its `--check` gate compares the whole file byte for byte, so these
//! tests live in their own module rather than in the generated table.

use super::types::CType;
use super::x86_builtin_types::result_type;

/// The 128-bit lane extracts return a 16-byte vector and the 256-bit lane
/// inserts return a 32-byte vector. `builtin_return_type` consults
/// `result_type` before any other table for these names, so each must have
/// exactly this width. A missing or wrongly sized entry would silently change
/// the ABI type of the call result.
#[test]
fn lane_builtins_have_result_types_of_the_architectural_width() {
    for name in [
        "__builtin_ia32_vextractf128_ps256",
        "__builtin_ia32_vextractf128_pd256",
        "__builtin_ia32_vextractf128_si256",
    ] {
        assert!(
            matches!(result_type(name), Some(CType::Vector(_, 16))),
            "{name} must return a 16-byte vector"
        );
    }
    for name in [
        "__builtin_ia32_vinsertf128_ps256",
        "__builtin_ia32_vinsertf128_pd256",
        "__builtin_ia32_vinsertf128_si256",
    ] {
        assert!(
            matches!(result_type(name), Some(CType::Vector(_, 32))),
            "{name} must return a 32-byte vector"
        );
    }
}

/// The 128-bit raw builtins whose duplicate arms were removed from
/// `builtin_return_type` must stay typed here, or their results would fall
/// through to a generic path.
#[test]
fn wide_raw_builtins_keep_their_result_types() {
    for name in [
        "__builtin_ia32_maxps",
        "__builtin_ia32_minps",
        "__builtin_ia32_shufps",
    ] {
        assert!(
            matches!(result_type(name), Some(CType::Vector(_, 16))),
            "{name} must return a 16-byte vector"
        );
    }
}
